'use strict';
const api=globalThis.RasnikiCatalog,$=id=>document.getElementById(id);
let page=1,counts={},selected=api.entries[0],generated='',mediaURL=null;
function select(entry){selected=entry;counts[entry.id]=(counts[entry.id]||0)+1;generated='';$('export').disabled=true;$('draft').textContent='Enter details and generate a new outline.';$('selected').textContent=entry.name+' — '+entry.status;$('review').textContent=entry.review;$('draft-status').textContent='Category selected. No draft generated.';render();}
function render(){const result=api.paginate(api.catalogue($('search').value,$('sort').value,counts),page);page=result.page;$('cards').replaceChildren();for(const entry of result.rows){const card=document.createElement('article');card.className='card';const heading=document.createElement('h2'),status=document.createElement('small'),purpose=document.createElement('p'),button=document.createElement('button');heading.textContent=entry.name;status.textContent=entry.status+' · local selections: '+(counts[entry.id]||0);purpose.textContent=entry.purpose;button.type='button';button.textContent='Use draft workspace';button.addEventListener('click',()=>{select(entry);$('workspace').scrollIntoView({behavior:'auto'});});card.append(heading,status,purpose,button);$('cards').append(card);}$('status').textContent=result.total+' categories · page '+result.page+' of '+result.pages+(!result.total?' · No matches':'');$('prev').disabled=page===1;$('next').disabled=page===result.pages;}
for(const id of ['search','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;render();});$('prev').addEventListener('click',()=>{page--;render();});$('next').addEventListener('click',()=>{page++;render();});$('clear').addEventListener('click',()=>{counts={};render();});
$('generate').addEventListener('click',()=>{const fields={};for(const id of ['title','purpose','locations','rights','acceptance'])fields[id]=$(id).value;generated=api.draft(selected,fields);$('draft').textContent=generated;$('export').disabled=false;$('draft-status').textContent='Unreviewed outline generated.';});
for(const id of ['title','purpose','locations','rights','acceptance'])$(id).addEventListener('input',()=>{generated='';$('export').disabled=true;$('draft-status').textContent='Inputs changed. Generate a new outline before exporting.';});
$('export').addEventListener('click',()=>{if(!generated)return;const url=URL.createObjectURL(new Blob([generated],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='rasniki-'+selected.id+'-draft.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function clearMedia(){for(const el of $('preview').querySelectorAll('audio,video')){el.pause();el.removeAttribute('src');el.load();}$('preview').replaceChildren();if(mediaURL)URL.revokeObjectURL(mediaURL);mediaURL=null;$('media').value='';$('media-status').textContent='Preview cleared.';}
$('remove-media').addEventListener('click',clearMedia);$('media').addEventListener('change',()=>{const file=$('media').files[0];clearMedia();if(!file)return;const kind=file.type.split('/')[0];if(!['image','audio','video'].includes(kind)){$('media-status').textContent='Choose a supported image, audio, or video file.';return;}if(file.size>50*1024*1024){$('media-status').textContent='Preview limit is 50 MiB.';return;}mediaURL=URL.createObjectURL(file);const el=document.createElement(kind==='image'?'img':kind);el.src=mediaURL;if(kind==='image')el.alt='Local preview: '+file.name;else el.controls=true;el.addEventListener('error',()=>{$('media-status').textContent='This media could not be decoded by the browser.';});$('preview').append(el);$('media-status').textContent='Local preview: '+file.name;});window.addEventListener('beforeunload',()=>{if(mediaURL)URL.revokeObjectURL(mediaURL);});
$('flip').addEventListener('click',()=>{try{const result=api.bitflip($('byte').value,$('bit').value);$('flip-output').textContent=result+' · binary '+result.toString(2).padStart(8,'0');}catch(e){$('flip-output').textContent=e.message;}});
$('calculate').addEventListener('click',()=>{try{$('calculation').textContent=api.exact($('a').value,$('b').value,$('operation').value);}catch(e){$('calculation').textContent=e.message;}});
$('selected').textContent=selected.name+' — '+selected.status;$('review').textContent=selected.review;render();
function openModule(){const match=/^#module=([A-Za-z0-9_-]+)$/.exec(window.location.hash);if(!match)return;const entry=api.entries.find(item=>item.id===match[1]);if(entry){select(entry);$('workspace').scrollIntoView({behavior:'auto'});}}
if(window.location)openModule();window.addEventListener('hashchange',openModule);
